{
  "rules": [
    "If sentiment is positive (≥0.2) in recent history, model tends to under-forecast; adjust forecast upward by 1-3% of recent mean.",
    "If model shows gradual upward trend with no spike, but true outcome shows sharp spike, model is lagging; add 2-5% buffer to forecast for spike periods.",
    "After a strong upward spike in true outcome, model often overshoots in next few days; reduce forecast by 1-2% for 3-5 day horizon.",
    "When sentiment is negative (≤0.0), model tends to over-forecast; reduce forecast by 1-3% to align with mean reversion.",
    "If model forecast is flat or slightly increasing but true outcome shows strong mean reversion, reduce forecast by 2-4% to reflect downward bias.",
    "For 30-day horizon, if model is consistently below true outcome by 5%+ over 3-5 days, apply upward correction based on sentiment momentum."
  ]
}
